/**
 * QR Code Generation Utility
 *
 * Client-side QR code generation for print documents.
 * Supports both verifiable (backend-signed URLs) and draft (reference-only) modes.
 *
 * Security Note:
 * - Verification signatures are generated by the backend (qr_utils.py)
 * - This utility only renders QR images from provided data
 * - Never generate HMAC signatures client-side
 */

import QRCode from 'qrcode';

// =============================================================================
// TYPES
// =============================================================================

/**
 * QR code error correction levels
 * Higher = more redundancy, larger code
 */
export type QRErrorCorrectionLevel = 'L' | 'M' | 'Q' | 'H';

/**
 * Options for QR code generation
 */
export interface QRCodeOptions {
  /** Width/height in pixels (default: 150) */
  size?: number;
  /** Margin in modules (default: 2) */
  margin?: number;
  /** Error correction level (default: 'M') */
  errorCorrectionLevel?: QRErrorCorrectionLevel;
  /** Dark color (default: '#000000') */
  darkColor?: string;
  /** Light color (default: '#ffffff') */
  lightColor?: string;
}

/**
 * QR content with verification status
 */
export interface QRContent {
  /** The data to encode in the QR code */
  data: string;
  /** Whether this QR contains a verifiable signed URL */
  isVerifiable: boolean;
  /** Human-readable label for the QR */
  label?: string;
}

/**
 * Document types for QR generation
 */
export type QRDocumentType =
  | 'prescription'
  | 'receipt'
  | 'invoice'
  | 'dispensing'
  | 'lab_result';

// =============================================================================
// QR CODE GENERATION
// =============================================================================

/**
 * Generate a QR code as a data URI (base64 PNG)
 *
 * @param data - The data to encode
 * @param options - QR code options
 * @returns Promise resolving to data URI string
 *
 * @example
 * ```typescript
 * const qrDataUri = await generateQRDataUri('https://vitora.health/verify?...');
 * // Returns: 'data:image/png;base64,iVBORw0KGgo...'
 * ```
 */
export async function generateQRDataUri(
  data: string,
  options: QRCodeOptions = {}
): Promise<string> {
  const {
    size = 150,
    margin = 2,
    errorCorrectionLevel = 'M',
    darkColor = '#000000',
    lightColor = '#ffffff',
  } = options;

  try {
    const dataUri = await QRCode.toDataURL(data, {
      width: size,
      margin,
      errorCorrectionLevel,
      color: {
        dark: darkColor,
        light: lightColor,
      },
    });

    return dataUri;
  } catch (error) {
    console.error('Failed to generate QR code:', error);
    // Return a placeholder on error
    return createPlaceholderDataUri(size);
  }
}

/**
 * Generate a QR code as SVG string
 *
 * Useful for inline SVG embedding without base64 overhead.
 *
 * @param data - The data to encode
 * @param options - QR code options
 * @returns Promise resolving to SVG string
 */
export async function generateQRSvg(
  data: string,
  options: QRCodeOptions = {}
): Promise<string> {
  const {
    size = 150,
    margin = 2,
    errorCorrectionLevel = 'M',
    darkColor = '#000000',
    lightColor = '#ffffff',
  } = options;

  try {
    const svg = await QRCode.toString(data, {
      type: 'svg',
      width: size,
      margin,
      errorCorrectionLevel,
      color: {
        dark: darkColor,
        light: lightColor,
      },
    });

    return svg;
  } catch (error) {
    console.error('Failed to generate QR SVG:', error);
    return createPlaceholderSvg(size);
  }
}

/**
 * Synchronous QR generation (for use in render functions)
 * Uses canvas element, returns data URI
 *
 * Note: This is slower than async version, use only when needed.
 */
export function generateQRDataUriSync(
  data: string,
  options: QRCodeOptions = {}
): string {
  const {
    size = 150,
    margin = 2,
    errorCorrectionLevel = 'M',
    darkColor = '#000000',
    lightColor = '#ffffff',
  } = options;

  // Create canvas element
  const canvas = document.createElement('canvas');

  try {
    QRCode.toCanvas(canvas, data, {
      width: size,
      margin,
      errorCorrectionLevel,
      color: {
        dark: darkColor,
        light: lightColor,
      },
    });

    return canvas.toDataURL('image/png');
  } catch (error) {
    console.error('Failed to generate QR code sync:', error);
    return createPlaceholderDataUri(size);
  }
}

// =============================================================================
// DOCUMENT-SPECIFIC QR CONTENT
// =============================================================================

/**
 * Get QR content for a prescription
 *
 * @param prescription - Prescription data
 * @returns QR content with verification status
 */
export function getPrescriptionQRContent(prescription: {
  prescription_number: string;
  verification_url?: string;
  id?: number;
}): QRContent {
  // Saved prescription with verification URL (backend-signed)
  if (prescription.verification_url) {
    return {
      data: prescription.verification_url,
      isVerifiable: true,
      label: 'Scan to verify prescription',
    };
  }

  // Saved prescription without verification URL
  if (prescription.id && prescription.id > 0) {
    return {
      data: `VITORA:RX:${prescription.prescription_number}`,
      isVerifiable: false,
      label: 'Reference only',
    };
  }

  // Draft/unsaved prescription
  return {
    data: `VITORA:DRAFT:${prescription.prescription_number}`,
    isVerifiable: false,
    label: 'Draft - not verified',
  };
}

/**
 * Get QR content for a dispensing record
 *
 * @param dispensing - Dispensing data
 * @returns QR content with verification status
 */
export function getDispensingQRContent(dispensing: {
  id: number;
  verification_url?: string;
  batch_number?: string;
}): QRContent {
  if (dispensing.verification_url) {
    return {
      data: dispensing.verification_url,
      isVerifiable: true,
      label: 'Scan to verify',
    };
  }

  // Fallback: encode dispensing ID and batch
  const data = dispensing.batch_number
    ? `VITORA:DISP:${dispensing.id}:${dispensing.batch_number}`
    : `VITORA:DISP:${dispensing.id}`;

  return {
    data,
    isVerifiable: false,
    label: 'Reference only',
  };
}

/**
 * Get QR content for a receipt
 *
 * @param receipt - Receipt data
 * @returns QR content with verification status
 */
export function getReceiptQRContent(receipt: {
  receipt_number: string;
  verification_url?: string;
  amount?: number | string;
}): QRContent {
  if (receipt.verification_url) {
    return {
      data: receipt.verification_url,
      isVerifiable: true,
      label: 'Scan to verify payment',
    };
  }

  return {
    data: `VITORA:RCPT:${receipt.receipt_number}`,
    isVerifiable: false,
    label: 'Reference only',
  };
}

/**
 * Get QR content for an invoice
 *
 * @param invoice - Invoice data
 * @returns QR content with verification status
 */
export function getInvoiceQRContent(invoice: {
  invoice_number: string;
  verification_url?: string;
  total_amount?: number | string;
}): QRContent {
  if (invoice.verification_url) {
    return {
      data: invoice.verification_url,
      isVerifiable: true,
      label: 'Scan to verify invoice',
    };
  }

  return {
    data: `VITORA:INV:${invoice.invoice_number}`,
    isVerifiable: false,
    label: 'Reference only',
  };
}

/**
 * Get QR content for a lab result
 *
 * @param labResult - Lab result data
 * @returns QR content with verification status
 */
export function getLabResultQRContent(labResult: {
  result_number?: string;
  order_number?: string;
  verification_url?: string;
}): QRContent {
  if (labResult.verification_url) {
    return {
      data: labResult.verification_url,
      isVerifiable: true,
      label: 'Scan to verify result',
    };
  }

  const ref = labResult.result_number || labResult.order_number || 'UNKNOWN';
  return {
    data: `VITORA:LAB:${ref}`,
    isVerifiable: false,
    label: 'Reference only',
  };
}

// =============================================================================
// PLACEHOLDERS
// =============================================================================

/**
 * Create a placeholder data URI when QR generation fails
 */
function createPlaceholderDataUri(size: number): string {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');

  if (ctx) {
    // White background
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, size, size);

    // Dashed border
    ctx.strokeStyle = '#999999';
    ctx.setLineDash([4, 4]);
    ctx.strokeRect(2, 2, size - 4, size - 4);

    // Text
    ctx.fillStyle = '#666666';
    ctx.font = `${Math.max(10, size / 10)}px Arial`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('QR', size / 2, size / 2);
  }

  return canvas.toDataURL('image/png');
}

/**
 * Create a placeholder SVG when QR generation fails
 */
function createPlaceholderSvg(size: number): string {
  return `
    <svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
      <rect width="${size}" height="${size}" fill="#ffffff"/>
      <rect x="2" y="2" width="${size - 4}" height="${size - 4}" fill="none" stroke="#999" stroke-dasharray="4,4"/>
      <text x="${size / 2}" y="${size / 2}" text-anchor="middle" dominant-baseline="middle" fill="#666" font-family="Arial" font-size="${Math.max(10, size / 10)}">QR</text>
    </svg>
  `.trim();
}

// =============================================================================
// HTML GENERATION FOR PRINT
// =============================================================================

/**
 * Generate complete HTML for a QR code block in printed documents
 *
 * Includes the QR image and appropriate label based on verification status.
 *
 * @param qrContent - QR content with verification status
 * @param options - QR code options
 * @returns Promise resolving to HTML string
 */
export async function generateQRBlockHtml(
  qrContent: QRContent,
  options: QRCodeOptions = {}
): Promise<string> {
  const { size = 90 } = options;
  const dataUri = await generateQRDataUri(qrContent.data, { ...options, size });

  const labelClass = qrContent.isVerifiable ? 'qr-label-verified' : 'qr-label-draft';
  const labelText = qrContent.label || (qrContent.isVerifiable ? 'Scan to verify' : 'Reference only');

  return `
    <div class="qr-block" style="text-align: center;">
      <img src="${dataUri}" alt="QR Code" width="${size}" height="${size}" style="display: block; margin: 0 auto;" />
      <div class="${labelClass}" style="font-size: 9px; margin-top: 4px; color: ${qrContent.isVerifiable ? '#166534' : '#92400e'};">
        ${qrContent.isVerifiable ? '✓ ' : '⚠ '}${labelText}
      </div>
    </div>
  `.trim();
}

/**
 * Generate QR block HTML synchronously (for render functions)
 */
export function generateQRBlockHtmlSync(
  qrContent: QRContent,
  options: QRCodeOptions = {}
): string {
  const { size = 90 } = options;
  const dataUri = generateQRDataUriSync(qrContent.data, { ...options, size });

  const labelClass = qrContent.isVerifiable ? 'qr-label-verified' : 'qr-label-draft';
  const labelText = qrContent.label || (qrContent.isVerifiable ? 'Scan to verify' : 'Reference only');

  return `
    <div class="qr-block" style="text-align: center;">
      <img src="${dataUri}" alt="QR Code" width="${size}" height="${size}" style="display: block; margin: 0 auto;" />
      <div class="${labelClass}" style="font-size: 9px; margin-top: 4px; color: ${qrContent.isVerifiable ? '#166534' : '#92400e'};">
        ${qrContent.isVerifiable ? '✓ ' : '⚠ '}${labelText}
      </div>
    </div>
  `.trim();
}
